#include "render/entity_animations.h"

#include <algorithm>
#include <stdexcept>

namespace entity_animation {
std::vector<std::string> Catalog::pack(AtlasAsset&atlas,LoadedImage&dst){auto pack_one=[&](std::optional<Strip>&entry){if(!entry)return;auto&s=*entry;try{const LoadedImage src=assets::load_png_rgba(s.image_path.string());const auto need_w=2*s.margin+s.columns*s.source_width+(s.columns-1)*s.spacing;if(src.width<need_w||src.height<s.source_height+2*s.margin)throw std::runtime_error("image geometry is too small");const std::uint32_t first=atlas.logical_tile_count,count=s.tile_count,columns=atlas.columns,tile=atlas.tile_width;const std::uint32_t rows=(first+count+columns-1)/columns;if(rows*tile>dst.height){dst.height=rows*tile;dst.rgba_pixels.resize(static_cast<std::size_t>(dst.width)*dst.height*4,0);}for(std::uint32_t n=0;n<count;++n){const auto dx=(first+n)%columns*tile,dy=(first+n)/columns*tile,sx=s.margin+n*(s.source_width+s.spacing);for(std::uint32_t y=0;y<tile;++y)for(std::uint32_t x=0;x<tile;++x){const auto si=(static_cast<std::size_t>(s.margin+y*s.source_height/tile)*src.width+sx+x*s.source_width/tile)*4;const auto di=(static_cast<std::size_t>(dy+y)*dst.width+dx+x)*4;std::copy_n(src.rgba_pixels.data()+si,4,dst.rgba_pixels.data()+di);}}for(auto&f:s.frames)f.atlas_index=first+f.tile_id;atlas.logical_tile_count+=count;}catch(const std::exception&x){warnings_.push_back("could not pack "+s.tsx_path.string()+": "+x.what());entry.reset();}};for(auto&player:players_)for(auto&entry:player)pack_one(entry);for(auto&entry:effects_)pack_one(entry);atlas.rows=dst.height/atlas.tile_height;return warnings_;}
} // namespace entity_animation
